"""Deterministic supported-sector wage ranking and archive replay matrix."""
from test_mobile_rendering import ROOT, html
from playwright.sync_api import sync_playwright
source=(ROOT/'assets/game.js').read_text()
probe=r'''window.__allocatorCase=(seed,kindA,kindB,scenario)=>{__townTest.reset('settlement',seed);const adults=G.people.filter(p=>!p.deceased&&!p.movedAway&&p.age>=16&&p.age<=70),pairs=[];for(const p of adults){for(const a of G.firms.filter(f=>f.kind===kindA&&!f.closed))for(const b of G.firms.filter(f=>f.kind===kindB&&!f.closed&&f.id!==a.id))if(workerCanCommute(p,a)&&workerCanCommute(p,b))pairs.push({p,a,b});}if(!pairs.length)return{seed,kindA,kindB,scenario,skipped:'no shared reachable adult/firms'};const {p,a,b}=pairs[0];for(const f of G.firms)if(f!==a&&f!==b)f.closed=true;for(const f of G.firms)f.workers=f.workers.filter(id=>id!==p.id);p.job=-1;p.publicWork=false;p.previousPublicRole='';p.searchAfter=0;for(const otherPerson of G.people)if(otherPerson!==p&&otherPerson.job<0)otherPerson.searchAfter=G.day+100;const cases={underfunded:{wa:90,wb:45,floor:28,tax:0},highA:{wa:52,wb:31,floor:28,tax:0},highB:{wa:31,wb:52,floor:28,tax:0},tie:{wa:40,wb:40,floor:28,tax:0},floorTie:{wa:24,wb:24,floor:40,tax:0},taxTie:{wa:52,wb:52,floor:28,tax:37},unreachable:{wa:45,wb:90,floor:28,tax:0}}[scenario];a.wage=cases.wa;b.wage=cases.wb;G.policy.minWage=cases.floor;G.policy.incomeTax=cases.tax;a.jobs=a.workers.length+1;b.jobs=b.workers.length+1;if(scenario==='unreachable'){const net=graph(),pa=net.portals.get(a.building),pb=net.portals.get(b.building);if(pa==null||pb==null||pa===pb)return{seed,kindA,kindB,scenario,skipped:'shared road portal'};for(const [dx,dy] of roadOffsets){const id=roadId(readBuild(b.building).x+dx,readBuild(b.building).y+dy);if(G.tiles[id]===1&&id!==pa)G.tiles[id]=0;}invalidateRoads(false);if(!workerCanCommute(p,a)||workerCanCommute(p,b))return{seed,kindA,kindB,scenario,skipped:'could not isolate one workplace'};}a.cash=scenario==='underfunded'?1:Math.max(a.cash,100000);b.cash=Math.max(b.cash,100000);const funded=f=>Math.min(workerIncome(f),Math.max(0,f.cash-workerIncome(f)*f.workers.length)/Math.max(1,f.jobs-f.workers.length)),eligible=[a,b].filter(f=>workerCanCommute(p,f)).sort((x,y)=>funded(y)-funded(x)||x.id-y.id),expected=eligible[0]?.id??-1;assignJobs();const assigned=p.job,reachable=assigned>=0&&workerCanCommute(p,G.firms[assigned]),pay=assigned>=0?workerIncome(G.firms[assigned]):0,paid=assigned<0?0:(()=>{const f=G.firms[assigned],w=workerIncome(f);let cash=f.cash,gross=0;for(const id of f.workers){const worker=G.people[id];if(!workerCanCommute(worker,f))continue;const amount=Math.min(w,cash);cash-=amount;if(id===p.id)gross=amount;}return gross;})();const archive=__townTest.save(),beforeJobs=JSON.stringify(G.people.map(x=>x.job));if(!__townTest.load(archive))throw Error('valid fixture archive rejected');assignJobs();const afterJobs=JSON.stringify(G.people.map(x=>x.job));return{seed,kindA,kindB,scenario,firmA:a.id,firmB:b.id,wageA:workerIncome(a),wageB:workerIncome(b),fundedA:funded(a),fundedB:funded(b),expected,assigned,assignedPay:pay,realizedGross:paid,realizedNet:paid*(1-G.policy.incomeTax/100),reachable,stable:beforeJobs===afterJobs,valid:validateTown()};};'''
baselineprobe=r"""window.__legacyWageOnly=(seed,a,b)=>{const saved=fundedVacancyIncome;fundedVacancyIncome=f=>workerIncome(f);try{return __allocatorCase(seed,a,b,'underfunded')}finally{fundedVacancyIncome=saved}};"""
seeds=[7,42,91,909]
scenarios=['underfunded','highA','highB','tie','floorTie','taxTie','unreachable']
sector_pairs=[('grocer','office'),('farm','factory'),('contractor','warehouse'),('bakery','tavern')]
results=[];skipped=[];baseline=[]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage']);p=b.new_page();p.set_default_timeout(120000);errs=[];p.on('pageerror',lambda e:errs.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n'+baselineprobe+'\n// SOURCE: 99-instrumentation.js'));p.evaluate("document.getElementById('newTown').click();paused=true")
 for seed in seeds:
  for pair in sector_pairs:
   for scenario in scenarios:
    r=p.evaluate('x=>__allocatorCase(x.seed,x.a,x.b,x.s)',{'seed':seed,'a':pair[0],'b':pair[1],'s':scenario})
    if 'skipped' not in r:results.append(r)
    else:skipped.append(r)
   baseline.append(p.evaluate('x=>__legacyWageOnly(x.seed,x.a,x.b)',{'seed':seed,'a':pair[0],'b':pair[1]}))
 b.close()
assert not errs,errs
assert results, 'No reachable supported sector pair fixtures'
assert len(baseline)==len(seeds)*len(sector_pairs) and all(x['assigned']!=x['expected'] for x in baseline),baseline
assert all(r['assigned']==r['expected'] and r['assignedPay']==(r['wageA'] if r['assigned']==r['firmA'] else r['wageB']) and r['realizedGross']==r['assignedPay'] and r['reachable'] and r['stable'] and r['valid']['ok'] for r in results),results
out=ROOT/'docs/evidence/food-shortage-recovery8/effective-wage-allocator-matrix.json';out.write_text(__import__('json').dumps({'source_sha256':__import__('hashlib').sha256(source.encode()).hexdigest(),'legacy_wage_only_underfunded_baseline':baseline,'cases':results,'count':len(results),'part_time':'not modeled in firm vacancy allocator','skipped_cases':skipped,'commute_fare':'not modeled for worker job assignment (road accessibility and transit access only)'},indent=2)+'\n')
print('PASS',len(results),'sector/pay/tie/tax/replay cases across seeds',seeds,'; part-time and fare ranking not modeled')
